-- ConnectionCyber — M13: domínio fiscal, NF-e/NFC-e e referência segura de A1.
-- Não armazena PFX, senha, CSC, token, chave privada, XML ou dado fiscal real.
begin;

create table public.erp_tax_regimes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,code text not null,name text not null,valid_from date not null,valid_to date,active boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,code,valid_from),unique(tenant_id,id),check(valid_to is null or valid_to>=valid_from));
create table public.erp_tax_profiles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,establishment_id uuid not null,regime_id uuid not null,environment text not null check(environment in('homologation','production')),uf char(2)not null,configuration jsonb not null default '{}'::jsonb,valid_from date not null,valid_to date,active boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,establishment_id,environment,valid_from),unique(tenant_id,id),foreign key(tenant_id,establishment_id)references public.erp_establishments(tenant_id,id)on delete restrict,foreign key(tenant_id,regime_id)references public.erp_tax_regimes(tenant_id,id)on delete restrict,check(valid_to is null or valid_to>=valid_from),check(jsonb_typeof(configuration)='object'and configuration::text!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'));
create table public.erp_tax_rules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,profile_id uuid not null,rule_key text not null,rule_version text not null,valid_from date not null,valid_to date,rule jsonb not null,source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),created_at timestamptz not null default now(),unique(tenant_id,profile_id,rule_key,valid_from),unique(tenant_id,id),foreign key(tenant_id,profile_id)references public.erp_tax_profiles(tenant_id,id)on delete restrict,check(valid_to is null or valid_to>=valid_from),check(jsonb_typeof(rule)='object'and rule::text!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'));
create table public.erp_fiscal_schema_versions(id uuid primary key default gen_random_uuid(),document_model text not null check(document_model in('55','65')),version text not null,technical_note text,valid_from date not null,valid_to date,artifact_hash text not null check(artifact_hash~'^[a-f0-9]{64}$'),status text not null check(status in('planned','homologation','active','retired')),created_at timestamptz not null default now(),unique(document_model,version),check(valid_to is null or valid_to>=valid_from));
create table public.erp_fiscal_series(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,establishment_id uuid not null,environment text not null check(environment in('homologation','production')),model text not null check(model in('55','65')),series integer not null check(series between 0 and 999),next_number bigint not null default 1 check(next_number>0),status text not null default 'active'check(status in('active','suspended','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint uq_fiscal_series_context unique(tenant_id,establishment_id,environment,model,series),unique(tenant_id,id),unique(tenant_id,id,establishment_id,environment,model,series),foreign key(tenant_id,establishment_id)references public.erp_establishments(tenant_id,id)on delete restrict);
create table public.erp_fiscal_number_reservations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,series_id uuid not null,number bigint not null check(number>0),idempotency_key text not null check(length(idempotency_key)between 16 and 200),status text not null default 'reserved'check(status in('reserved','used','released','invalidated')),reserved_at timestamptz not null default now(),used_at timestamptz,unique(tenant_id,series_id,number),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,series_id)references public.erp_fiscal_series(tenant_id,id)on delete restrict,check((status='used'and used_at is not null)or(status<>'used'and used_at is null)));
alter table public.erp_sales add constraint erp_sales_tenant_establishment_id_unique unique(tenant_id,establishment_id,id);
create table public.erp_fiscal_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,establishment_id uuid not null,sale_id uuid,series_id uuid not null,reservation_id uuid not null,environment text not null check(environment in('homologation','production')),model text not null check(model in('55','65')),series integer not null,number bigint not null,access_key_hash text check(access_key_hash is null or access_key_hash~'^[a-f0-9]{64}$'),schema_version text not null,tax_snapshot jsonb not null,totals_snapshot jsonb not null,idempotency_key text not null check(length(idempotency_key)between 16 and 200),status text not null default 'draft'check(status in('draft','validated','queued','signing','signed','transmitting','authorized','rejected','denied','contingency_pending','cancelled')),issued_at timestamptz not null,authorized_at timestamptz,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint uq_fiscal_document_number unique(tenant_id,environment,model,series,number),unique(tenant_id,idempotency_key),unique(tenant_id,reservation_id),unique(tenant_id,id),unique(tenant_id,id,model),foreign key(tenant_id,establishment_id)references public.erp_establishments(tenant_id,id)on delete restrict,foreign key(tenant_id,establishment_id,sale_id)references public.erp_sales(tenant_id,establishment_id,id)on delete restrict,foreign key(tenant_id,series_id,establishment_id,environment,model,series)references public.erp_fiscal_series(tenant_id,id,establishment_id,environment,model,series)on delete restrict,foreign key(tenant_id,reservation_id)references public.erp_fiscal_number_reservations(tenant_id,id)on delete restrict,foreign key(model,schema_version)references public.erp_fiscal_schema_versions(document_model,version)on delete restrict,check(length(btrim(schema_version))between 1 and 50),check(jsonb_typeof(tax_snapshot)='object'and jsonb_typeof(totals_snapshot)='object'),check((tax_snapshot::text||totals_snapshot::text)!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'));
create table public.erp_fiscal_document_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,document_id uuid not null,line integer not null check(line>0),source_item_id uuid,description text not null,tax_snapshot jsonb not null,totals_snapshot jsonb not null,created_at timestamptz not null default now(),unique(tenant_id,document_id,line),unique(tenant_id,id),foreign key(tenant_id,document_id)references public.erp_fiscal_documents(tenant_id,id)on delete restrict,check(jsonb_typeof(tax_snapshot)='object'and jsonb_typeof(totals_snapshot)='object'),check((tax_snapshot::text||totals_snapshot::text)!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'));
create table public.erp_fiscal_transmissions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,document_id uuid not null,provider text not null,provider_document_id text,attempt integer not null check(attempt>0),request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),response_hash text check(response_hash is null or response_hash~'^[a-f0-9]{64}$'),status text not null check(status in('queued','sent','unknown','acknowledged','failed')),started_at timestamptz not null default now(),finished_at timestamptz,error_code text,error_detail text,unique(tenant_id,document_id,attempt),unique(tenant_id,id),foreign key(tenant_id,document_id)references public.erp_fiscal_documents(tenant_id,id)on delete restrict,check(error_detail is null or error_detail!~*'(password|senha|token|secret|credential|private.key|certificate|pfx|csc)'));
create unique index erp_fiscal_transmissions_provider_document_unique on public.erp_fiscal_transmissions(tenant_id,provider,provider_document_id)where provider_document_id is not null;
create table public.erp_fiscal_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,document_id uuid not null,event_type text not null check(event_type in('validated','queued','signing','signed','transmitted','authorized','rejected','denied','contingency_entered','contingency_exited','cancelled','number_invalidated','reconciled')),from_status text,to_status text,idempotency_key text not null check(length(idempotency_key)between 16 and 200),provider_event_id text,payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),detail jsonb not null default '{}'::jsonb,occurred_at timestamptz not null,recorded_at timestamptz not null default now(),actor_id uuid references auth.users(id),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,document_id)references public.erp_fiscal_documents(tenant_id,id)on delete restrict,check(jsonb_typeof(detail)='object'and detail::text!~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'));
create unique index erp_fiscal_events_provider_event_unique on public.erp_fiscal_events(tenant_id,provider_event_id)where provider_event_id is not null;
create table public.erp_fiscal_xml_artifacts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,document_id uuid not null,kind text not null check(kind in('signed_xml','authorized_xml','event_xml','protocol','danfe')),storage_ref text not null,content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),schema_version text not null,immutable boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,document_id,kind,content_hash),unique(tenant_id,id),foreign key(tenant_id,document_id)references public.erp_fiscal_documents(tenant_id,id)on delete restrict,check(storage_ref!~*'(https?://[^ ]+@|password|senha|token|secret|pfx|csc)'));
create table public.erp_fiscal_contingencies(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,document_id uuid not null,document_model text not null default '65'check(document_model='65'),mode text not null check(mode='offline_nfce'),uf char(2)not null,rule_version text not null,reason text not null,entered_at timestamptz not null,exited_at timestamptz,transmit_by timestamptz,status text not null default 'active'check(status in('active','transmitting','reconciled','expired','manual_review')),created_at timestamptz not null default now(),unique(tenant_id,document_id),unique(tenant_id,id),foreign key(tenant_id,document_id,document_model)references public.erp_fiscal_documents(tenant_id,id,model)on delete restrict,check(exited_at is null or exited_at>=entered_at));
create table public.erp_certificate_refs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,establishment_id uuid not null,custody_mode text not null check(custody_mode in('provider_custody','remote_hsm','managed_vault','electronic_seal')),secret_ref text not null,subject_cnpj_hash text not null check(subject_cnpj_hash~'^[a-f0-9]{64}$'),serial_number_hash text not null check(serial_number_hash~'^[a-f0-9]{64}$'),thumbprint text not null check(thumbprint~'^[a-f0-9]{64}$'),valid_from timestamptz not null,valid_to timestamptz not null,status text not null default 'pending'check(status in('pending','active','expiring','expired','revoked','destroyed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint uq_certificate_ref_thumbprint unique(tenant_id,establishment_id,custody_mode,thumbprint),unique(tenant_id,id),foreign key(tenant_id,establishment_id)references public.erp_establishments(tenant_id,id)on delete restrict,check(valid_to>valid_from),check(secret_ref~'^(vault|hsm|provider|seal)://[A-Za-z0-9._:/-]{8,240}$'));
create table public.erp_fiscal_webhook_inbox(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id)on delete cascade,provider text not null,environment text not null check(environment in('homologation','production')),provider_event_id text not null,payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),signature_verified_at timestamptz not null,received_at timestamptz not null default now(),processed_at timestamptz,status text not null default 'received'check(status in('received','processing','processed','rejected','manual_review')),error_code text,constraint uq_fiscal_webhook_event unique(tenant_id,provider,environment,provider_event_id),unique(tenant_id,provider,environment,payload_hash),unique(tenant_id,id));

insert into public.erp_permissions(key,name,description,category)values('fiscal.read','Consultar fiscal','Consulta documentos fiscais do tenant.','Fiscal'),('fiscal.issue','Emitir documento fiscal','Solicita e acompanha emissão fiscal.','Fiscal'),('fiscal.cancel','Cancelar documento fiscal','Registra cancelamento e inutilização com AAL2.','Fiscal'),('fiscal.configure','Configurar fiscal','Mantém perfis, regras, séries e ambientes com AAL2.','Fiscal'),('fiscal.certificate.manage','Gerenciar referência de certificado','Mantém somente referência protegida com AAL2.','Fiscal'),('fiscal.audit','Auditar fiscal','Consulta eventos, transmissões e artefatos.','Fiscal')on conflict(key)do update set name=excluded.name,description=excluded.description,category=excluded.category,active=true;

create or replace function public.erp_reserve_fiscal_number(p_tenant_id uuid,p_establishment_id uuid,p_environment text,p_model text,p_series integer,p_idempotency_key text)returns table(reservation_id uuid,number bigint)language plpgsql security definer set search_path=''as $$declare v_series_id uuid;v_number bigint;v_id uuid;begin if erp_security.current_aal()<>'aal2'or not(erp_security.has_permission(p_tenant_id,'fiscal.issue')or public.is_platform_staff())then raise exception 'permission and aal2 required';end if;if p_environment not in('homologation','production')or p_model not in('55','65')or p_series not between 0 and 999 or length(btrim(p_idempotency_key))not between 16 and 200 then raise exception 'invalid fiscal scope';end if;if p_environment='production'and coalesce(current_setting('app.fiscal_production_enabled',true),'false')<>'true'then raise exception 'fiscal production disabled';end if;select r.id,r.number into v_id,v_number from public.erp_fiscal_number_reservations r where r.tenant_id=p_tenant_id and r.idempotency_key=p_idempotency_key;if v_id is not null then return query select v_id,v_number;return;end if;select id,next_number into v_series_id,v_number from public.erp_fiscal_series where tenant_id=p_tenant_id and establishment_id=p_establishment_id and environment=p_environment and model=p_model and series=p_series and status='active'for update;if v_series_id is null then raise exception 'active fiscal series not found';end if;select r.id,r.number into v_id,v_number from public.erp_fiscal_number_reservations r where r.tenant_id=p_tenant_id and r.idempotency_key=p_idempotency_key;if v_id is not null then return query select v_id,v_number;return;end if;insert into public.erp_fiscal_number_reservations(tenant_id,series_id,number,idempotency_key)values(p_tenant_id,v_series_id,v_number,btrim(p_idempotency_key))returning id into v_id;update public.erp_fiscal_series set next_number=v_number+1,updated_at=now()where tenant_id=p_tenant_id and id=v_series_id;return query select v_id,v_number;end$$;
create or replace function public.erp_create_fiscal_document(p_tenant_id uuid,p_establishment_id uuid,p_sale_id uuid,p_reservation_id uuid,p_schema_version text,p_tax_snapshot jsonb,p_totals_snapshot jsonb,p_issued_at timestamptz,p_idempotency_key text)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_series record;begin if not(erp_security.has_permission(p_tenant_id,'fiscal.issue')or public.is_platform_staff())then raise exception 'permission required';end if;if jsonb_typeof(p_tax_snapshot)<>'object'or jsonb_typeof(p_totals_snapshot)<>'object'or length(btrim(p_idempotency_key))not between 16 and 200 then raise exception 'invalid fiscal request';end if;if(p_tax_snapshot::text||p_totals_snapshot::text)~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'then raise exception 'secret field forbidden';end if;select id into v_id from public.erp_fiscal_documents where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key;if v_id is not null then return v_id;end if;select s.id,s.environment,s.model,s.series,r.number into v_series from public.erp_fiscal_number_reservations r join public.erp_fiscal_series s on s.tenant_id=r.tenant_id and s.id=r.series_id where r.tenant_id=p_tenant_id and r.id=p_reservation_id and r.status='reserved'for update of r;if v_series.id is null then raise exception 'reservation not available';end if;select id into v_id from public.erp_fiscal_documents where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key;if v_id is not null then return v_id;end if;insert into public.erp_fiscal_documents(tenant_id,establishment_id,sale_id,series_id,reservation_id,environment,model,series,number,schema_version,tax_snapshot,totals_snapshot,idempotency_key,issued_at)values(p_tenant_id,p_establishment_id,p_sale_id,v_series.id,p_reservation_id,v_series.environment,v_series.model,v_series.series,v_series.number,btrim(p_schema_version),p_tax_snapshot,p_totals_snapshot,p_idempotency_key,p_issued_at)returning id into v_id;update public.erp_fiscal_number_reservations set status='used',used_at=now()where tenant_id=p_tenant_id and id=p_reservation_id;return v_id;end$$;
create or replace function public.erp_transition_fiscal_document(p_tenant_id uuid,p_document_id uuid,p_to_status text,p_event_type text,p_payload_hash text,p_detail jsonb,p_idempotency_key text)returns uuid language plpgsql security definer set search_path=''as $$declare v_from text;v_allowed boolean;v_expected_event text;v_broker boolean:=auth.role()='service_role';begin if v_broker then if p_to_status not in('signing','signed','transmitting','authorized','rejected','denied','contingency_pending')then raise exception 'broker transition forbidden';end if;else if p_to_status='cancelled'then if erp_security.current_aal()<>'aal2'or not(erp_security.has_permission(p_tenant_id,'fiscal.cancel')or public.is_platform_staff())then raise exception 'cancel permission and aal2 required';end if;elsif p_to_status not in('validated','queued')or not(erp_security.has_permission(p_tenant_id,'fiscal.issue')or public.is_platform_staff())then raise exception 'operator transition forbidden';end if;end if;if exists(select 1 from public.erp_fiscal_events where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key and document_id=p_document_id and to_status=p_to_status)then return p_document_id;end if;v_expected_event:=case p_to_status when'validated'then'validated'when'queued'then'queued'when'signing'then'signing'when'signed'then'signed'when'transmitting'then case when p_event_type='contingency_exited'then'contingency_exited'else'transmitted'end when'authorized'then'authorized'when'rejected'then'rejected'when'denied'then'denied'when'contingency_pending'then'contingency_entered'when'cancelled'then'cancelled'end;if v_expected_event is null or p_event_type<>v_expected_event then raise exception 'event and status mismatch';end if;if p_payload_hash!~'^[a-f0-9]{64}$'or jsonb_typeof(p_detail)<>'object'or p_detail::text~*'"(password|senha|secret|token|credential|private_key|service_role|certificate|certificado|pfx|p12|csc|id_token)"[[:space:]]*:'then raise exception 'invalid event evidence';end if;select status into v_from from public.erp_fiscal_documents where tenant_id=p_tenant_id and id=p_document_id for update;if v_from is null then raise exception 'document not found';end if;if exists(select 1 from public.erp_fiscal_events where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key and document_id=p_document_id and to_status=p_to_status)then return p_document_id;end if;v_allowed:=case v_from when'draft'then p_to_status='validated'when'validated'then p_to_status='queued'when'queued'then p_to_status in('signing','contingency_pending')when'signing'then p_to_status in('signed','rejected')when'signed'then p_to_status in('transmitting','contingency_pending')when'transmitting'then p_to_status in('authorized','rejected','denied','contingency_pending')when'contingency_pending'then p_to_status='transmitting'when'authorized'then p_to_status='cancelled'else false end;if not v_allowed then raise exception 'invalid state transition';end if;update public.erp_fiscal_documents set status=p_to_status,authorized_at=case when p_to_status='authorized'then now()else authorized_at end,cancelled_at=case when p_to_status='cancelled'then now()else cancelled_at end,updated_at=now()where tenant_id=p_tenant_id and id=p_document_id;insert into public.erp_fiscal_events(tenant_id,document_id,event_type,from_status,to_status,idempotency_key,payload_hash,detail,occurred_at,actor_id)values(p_tenant_id,p_document_id,p_event_type,v_from,p_to_status,p_idempotency_key,p_payload_hash,p_detail,now(),auth.uid());return p_document_id;end$$;
create or replace function public.erp_ingest_fiscal_provider_event(p_tenant_id uuid,p_provider text,p_environment text,p_provider_event_id text,p_payload_hash text,p_signature_verified_at timestamptz)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;begin if auth.role()<>'service_role'then raise exception 'broker only';end if;if p_environment not in('homologation','production')or p_payload_hash!~'^[a-f0-9]{64}$'or p_signature_verified_at is null or length(btrim(p_provider_event_id))not between 1 and 200 or length(btrim(p_provider))not between 2 and 50 then raise exception 'invalid provider event';end if;if p_environment='production'and coalesce(current_setting('app.fiscal_production_enabled',true),'false')<>'true'then raise exception 'fiscal production disabled';end if;insert into public.erp_fiscal_webhook_inbox(tenant_id,provider,environment,provider_event_id,payload_hash,signature_verified_at)values(p_tenant_id,btrim(p_provider),p_environment,btrim(p_provider_event_id),p_payload_hash,p_signature_verified_at)on conflict(tenant_id,provider,environment,provider_event_id)do update set provider_event_id=excluded.provider_event_id returning id into v_id;return v_id;end$$;

do $$declare t text;begin foreach t in array array['erp_tax_regimes','erp_tax_profiles','erp_tax_rules','erp_fiscal_schema_versions','erp_fiscal_series','erp_fiscal_number_reservations','erp_fiscal_documents','erp_fiscal_document_items','erp_fiscal_transmissions','erp_fiscal_events','erp_fiscal_xml_artifacts','erp_fiscal_contingencies','erp_certificate_refs','erp_fiscal_webhook_inbox']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
create policy erp_tax_regimes_select on public.erp_tax_regimes for select to authenticated using(erp_security.has_permission(tenant_id,'fiscal.read')or erp_security.has_permission(tenant_id,'fiscal.configure')or public.is_platform_staff());
create policy erp_tax_profiles_select on public.erp_tax_profiles for select to authenticated using(erp_security.has_permission(tenant_id,'fiscal.read')or erp_security.has_permission(tenant_id,'fiscal.configure')or public.is_platform_staff());
create policy erp_tax_rules_select on public.erp_tax_rules for select to authenticated using(erp_security.has_permission(tenant_id,'fiscal.read')or erp_security.has_permission(tenant_id,'fiscal.configure')or public.is_platform_staff());
create policy erp_fiscal_documents_select on public.erp_fiscal_documents for select to authenticated using(erp_security.has_permission(tenant_id,'fiscal.read')or erp_security.has_permission(tenant_id,'fiscal.audit')or public.is_platform_staff());
create policy erp_fiscal_document_items_select on public.erp_fiscal_document_items for select to authenticated using(erp_security.has_permission(tenant_id,'fiscal.read')or erp_security.has_permission(tenant_id,'fiscal.audit')or public.is_platform_staff());
